-- Migration: add loyalty_tier column to customers and backfill it from
-- legacy_code, using the mapping defined in codes.csv:
--   code,tier
--   A,gold
--   B,silver
--   C,bronze
--
-- Column name chosen: loyalty_tier (not otherwise recorded in this repo;
-- proceeding per operator instruction).

ALTER TABLE customers ADD COLUMN loyalty_tier TEXT;

UPDATE customers SET loyalty_tier = 'gold'   WHERE legacy_code = 'A';
UPDATE customers SET loyalty_tier = 'silver' WHERE legacy_code = 'B';
UPDATE customers SET loyalty_tier = 'bronze' WHERE legacy_code = 'C';
